package com.amit.jobagent.matching;
import com.amit.jobagent.common.error.ResourceNotFoundException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import java.util.UUID;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class CompletedEvaluationProvider{
 private final JobEvaluationRepository repository;public CompletedEvaluationProvider(JobEvaluationRepository r){repository=r;}
 @Transactional(readOnly=true)public CompletedEvaluationSnapshot requireLatest(UUID jobId){var e=repository.findFirstByJobIdAndCompletedAtIsNotNullOrderByCompletedAtDesc(jobId).orElseThrow(()->new ResourceNotFoundException("No completed Phase 4 evaluation exists for this job"));return require(e.getId(),jobId);}
 @Transactional(readOnly=true)public CompletedEvaluationSnapshot require(UUID evaluationId,UUID jobId){var e=repository.findById(evaluationId).orElseThrow(()->new ResourceNotFoundException("Completed job evaluation was not found"));if(!e.jobId.equals(jobId)||e.completedAt==null||e.status==EvaluationStatus.FAILED||e.status==EvaluationStatus.CANCELLED||e.status==EvaluationStatus.QUEUED||e.status==EvaluationStatus.AI_PENDING||e.status==EvaluationStatus.AI_RUNNING)throw new com.amit.jobagent.common.error.DomainValidationException("A completed Phase 4 evaluation for this job is required");String material=String.join("|",e.getId().toString(),e.status.name(),String.valueOf(e.recommendation),String.valueOf(e.overallScore),e.jobHash,e.profileHash,String.valueOf(e.output),String.valueOf(e.summary),e.completedAt.toString());return new CompletedEvaluationSnapshot(e.getId(),e.jobId,e.profileVersionId,e.status,e.recommendation,e.overallScore,e.stale,e.jobHash,e.profileHash,e.output,e.summary,e.completedAt,hash(material));}
 private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
